import{_ as t,o as a,c as o,a8 as r}from"./chunks/framework.DpsX1MbM.js";const m=JSON.parse('{"title":"EAGLE3","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/EAGLE3.md","filePath":"sections/concepts/EAGLE3.md","lastUpdated":1788846900000}'),s={name:"concepts/EAGLE3.md"};function n(i,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="eagle3" tabindex="-1">EAGLE3 <a class="header-anchor" href="#eagle3" aria-label="Permalink to &quot;EAGLE3&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>In the previous speculative decoding practices, we usually choose a small language model from the same family as the draft model. For example, we can use <code>Llama-3.1-8B-Instruct</code> as the draft model and <code>Llama-3.1-70B-Instruct</code> as the target model. However, this approach is not always feasible because the small language model may not always be available. Thus, researchers have proposed to train a separate small model as the speculator, this type of models usually use the target model&#39;s hidden states or KV cache as input to predict the next few tokens.</p><p>Among this type of models, EAGLE3 is the state-of-the-art and has been integrated in <a href="https://github.com/sgl-project/sglang" target="_blank" rel="noreferrer">SGLang</a>. It relies on the hidden states of the target model and often consists of only one dense decoder layer. Before you read on, you can revisit the details of <a href="./speculative_decoding.html">speculative decoding</a> first if not familiar.</p><h2 id="how-it-works" tabindex="-1">How it works? <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works?&quot;">​</a></h2><p align="center"><img src="https://developer-blogs.nvidia.com/wp-content/uploads/2025/09/speculative-decoding-eagle-drafting-mechanism.gif" alt="EAGLE3"><br><span>Source: <a href="https://developer.nvidia.com/blog/an-introduction-to-speculative-decoding-for-reducing-latency-in-ai-inference/">Blog by NVIDIA</a></span></p><p>The workflow of EAGLE3 is shown in the animation above. It differs from other speculative decoding methods in several ways:</p><ol><li><strong><code>Feature-based Drafting</code></strong>: Unlike other speculative decoding methods which directly feeds the tokens to the draft model to generate predictions, EAGLE3 operates in the feature space. It will extract the 3 hidden states from the target model at 3 layers at different depths and concatenate them together to form a single feature vector. This feature vector will be fed to the draft model to generate predictions.</li><li><strong><code>Training-time Test</code></strong>: During training, EAGLE3 simulate the autoregressive generation process by autoregressively generating the next few tokens. It then computes the loss between the predicted output sequence and the ground truth sequence. This method improves the draft model performance because it reduces the generation errors accumulated from previous tokens for higher acceptance rate.</li><li><strong><code>Dynamic Draft Tree</code></strong>: EAGLE3 uses a dynamic draft tree to store the candidate tokens as proposed in <a href="https://arxiv.org/abs/2406.16858" target="_blank" rel="noreferrer">EAGLE2</a>. In simple words, it will only store the candidate tokens that are most likely to be accepted by the target model to improve the acceptance rate.</li></ol>',8)])])}const f=t(s,[["render",n]]);export{m as __pageData,f as default};
